<?php
function beheerFaqMagOpenen(): bool { if (empty($GLOBALS['ingelogd'])) return false; if (!empty($GLOBALS['isMaster'])) return true; return in_array('faq', (array)($GLOBALS['toegestaneTabs'] ?? []), true); }
function beheerFaqBewaakLegacyPost(): void { if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST' || (string)($_POST['formulier'] ?? '') !== 'faq') return; $_POST['formulier']=''; if(function_exists('schrijfLog')) schrijfLog($GLOBALS['logBestand'],$GLOBALS['huidigeGebruiker'],'legacy_faq_geblokkeerd','faq'); }
function beheerFaqStartOutputFilter(): void { ob_start(function($html){ if(!is_string($html))return $html; if(beheerFaqMagOpenen())$html=preg_replace('~<button\s+type="button"\s+class="menu-item"\s+data-tab="faq">.*?</button>~is','<a class="menu-item menu-item-link" style="display:block;text-decoration:none" href="faq.php">* Vragen</a>',$html,1)??$html; if(stripos($html,'</head>')!==false)$html=preg_replace('~</head>~i','<style>#tab-faq{display:none!important}</style></head>',$html,1)??$html; return $html;}); }
beheerFaqBewaakLegacyPost(); beheerFaqStartOutputFilter();
